"""Assignment rule v2, discovered by watching a model reason.

FROZEN 2026-08-31. Built on the ten development cases in
evals/cases/gate-4-narrow.json. Scoring it on those cases proves nothing — they
shaped it. It is tested only on a fresh labelled set.

The rule the model exposed: evidence for an assignment must sit in the job title
or in text describing the role. Company description never assigns the role.
"""

import re

# Therapy-area terms that may appear in a title. The mapping from a franchise name
# to the indications it covers is domain judgment and Venkat's to confirm.
TITLE_TERMS = {
    "obesity": [rb"\bobesit"],
    "type 2 diabetes": [rb"\bdiabet"],
}
FRANCHISE_TERMS = {
    rb"\bcardiometabolic\b": ["obesity", "type 2 diabetes"],
}

# A sentence describing what the job is or does.
ROLE_MARKERS = re.compile(
    rb"\byou will\b|\byour new role\b|\bthis role\b|\bthe position\b|\bthe job\b|"
    rb"\bresponsible for\b|\bserves? as\b|\bleads?\b|\bmanages?\b|\bdrives?\b|"
    rb"\byour opportunity\b|\bare you a\b|\bwe are looking for\b|\byou'll\b|"
    rb"\bpromoting\b|\bsupporting\b|\bbuild and lead\b|\bunderstanding of\b|"
    rb"\bis needed\b|\brequired\b", re.I)

# Candidate background rather than role scope. "is a plus" does not assign;
# "is needed" alongside a matching title does. Venkat, 2026-08-31.
WEAK_ONLY = re.compile(rb"\bis a plus\b|\bpreferred\b|\bdesirable\b|\bnice to have\b", re.I)


def from_title(title):
    if not title:
        return []
    t = title.encode() if isinstance(title, str) else title
    found = set()
    for name, pats in TITLE_TERMS.items():
        if any(re.search(p, t, re.I) for p in pats):
            found.add(name)
    for pat, names in FRANCHISE_TERMS.items():
        if re.search(pat, t, re.I):
            found.update(names)
    return sorted(found)


def from_role_text(sentences, boilerplate, indications):
    found = set()
    for s in sentences:
        if s in boilerplate:
            continue                       # company description
        if not ROLE_MARKERS.search(s):
            continue                       # not describing the role
        if WEAK_ONLY.search(s):
            continue                       # candidate background only
        for name, pat in indications.items():
            if pat.search(s):
                found.add(name)
    return sorted(found)


def decide(title, sentences, boilerplate, indications):
    """assign one indication, or refuse. Returns (decision, indication, why)."""
    t = from_title(title)
    if len(t) == 1:
        return "assign", t[0], "the job title names the therapy area"
    if len(t) > 1:
        r = from_role_text(sentences, boilerplate, indications)
        if len(r) == 1:
            return "assign", r[0], "title names a franchise; role text narrows it to one"
        return "refuse", None, f"title names a franchise covering {', '.join(t)}; role text does not narrow it"
    r = from_role_text(sentences, boilerplate, indications)
    if len(r) == 1:
        return "assign", r[0], "role text names it outside company description"
    if len(r) > 1:
        return "refuse", None, f"role text names more than one ({', '.join(r)}); neither chosen"
    return "refuse", None, "no therapy area in the title or in role-describing text"
