"""Generate fresh candidates for Venkat to label, weighted to hard cases."""
import sqlite3, pathlib, re, json, html as ht, sys
sys.path.insert(0, "."); import refuse
c = sqlite3.connect("data/telegraph.sqlite")
dev = {x["id"] for x in json.loads(pathlib.Path("evals/cases/gate-4-narrow.json").read_text())
       for x in [x]} if False else set()
dev_ids = {x["case"] for x in json.loads(pathlib.Path("evals/cases/gate-4-narrow.json").read_text())}
seen = {r[0] for r in c.execute("SELECT subject FROM refusal")}
bp, _, _ = refuse.build_boilerplate(c)

buckets = {"boundary": [], "adversarial": [], "easy": []}
for eid, title, rp in c.execute("""SELECT p.evidence_id, p.title, e.raw_path FROM parsed p
        JOIN evidence e ON e.evidence_id=p.evidence_id WHERE p.relevance='in scope'"""):
    html = pathlib.Path(rp).read_bytes()
    sents = refuse.sentences(html)
    hits = [s for s in sents if re.search(rb"\bobesit|\bdiabet", s, re.I)]
    if not hits: continue
    in_bp  = any(s in bp for s in hits)
    in_role = any(s not in bp and refuse.CANDIDATE_LANGUAGE.search(s) is None and
                  re.search(rb"you will|your new role|this role|responsible for|promoting|are you a", s, re.I)
                  for s in hits)
    weak   = any(re.search(rb"is a plus|preferred|experience (in|with|within)|understanding of", s, re.I) for s in hits)
    if in_bp and in_role:   buckets["adversarial"].append((eid, title))
    elif weak:              buckets["boundary"].append((eid, title))
    else:                   buckets["easy"].append((eid, title))

print("Fresh candidates found in the corpus, by difficulty:\n")
for k in ("adversarial", "boundary", "easy"):
    print(f"  {k:12} {len(buckets[k]):>3} available")
pathlib.Path("evals/cases/gate-4-fresh-candidates.json").write_text(
    json.dumps({k: [{"id": e[-8:], "title": ht.unescape(t or "")} for e, t in v] for k, v in buckets.items()}, indent=2))
print("\n  written to evals/cases/gate-4-fresh-candidates.json")
