def subtype_of(area, sentence):
    """The subtype the sentence states, or None for stated-but-unspecified.

    None is a finding, not a gap. It records that the posting named the area and
    did not name a subtype, which is different from the posting saying nothing.
    """
    for name, pat in SUBTYPE.get(area, []):
        if pat.search(sentence):
            return name
    return None


def areas_in_role_text(html, boilerplate):
    """Disease areas named in sentences that describe the job itself.

    Returns {area: (subtype, basis_sentence)}. A sentence naming a subtype wins
    over one that does not, so a posting saying "diabetes" in one place and
    "type 2 diabetes" in another records type 2 and cites the sentence that
    actually said it.
    """
    found = {}
    for sent in sentences(html):
        if sent in boilerplate:
            continue                      # company language
        if CANDIDATE_LANGUAGE.search(sent):
            continue                      # who they want to hire, not what the job is
        for area, pat in DETECT.items():
            if not pat.search(sent):
                continue
            sub = subtype_of(area, sent)
            if area not in found or (sub and not found[area][0]):
                found[area] = (sub, sent.decode("utf-8", "replace")[:400])
    return found

