PER_REQUEST_NOISE = [
    # Security token, regenerated per request.
    re.compile(rb'"X-CSRF-Token"\s*:\s*"[^"]*"'),
    # Visitor identifier, regenerated per request.
    re.compile(rb"var ctid = '[^']*';"),
    # The site's own internal labels for form fields, e.g. j_idt161. Their
    # page software renumbers these between builds. Nothing to do with content.
    re.compile(rb"j_idt\d+"),
    # Cache-busting number on script addresses, e.g. override.js?locale=en_GB&i=325369552
    # The separator arrives HTML-encoded as &amp;i= so an [?&] class misses it.
    re.compile(rb"i=\d{6,}"),
]


def stable_digest(body):
    """Fingerprint of the page with per-request tokens removed."""
    masked = body
    for pattern in PER_REQUEST_NOISE:
        masked = pattern.sub(b"<masked>", masked)
    return hashlib.sha256(masked).hexdigest()


def now_utc():
