def fetch(url):
    """Fetch a URL. Sends the default Python identifier — approved 2026-08-30."""
    with urllib.request.urlopen(url, timeout=TIMEOUT_SECONDS) as response:
        return response.status, response.read()


class SourceNotValid(Exception):
    """The response arrived but is not the document this task expects.

    Novo answers 200 for every address, serving a different document rather than
    an error. A successful fetch of valid XML is not evidence the right thing
    came back. This was documented in docs/sources/novo-nordisk.md before the
    collector was written and never became a control, which is how 318 jobs were
    once recorded as having vanished when nothing had.
    """


