    """Confirm the response is the job list, not merely something well-formed."""
    root_tag = ET.fromstring(xml_bytes).tag.split("}")[-1]
    if root_tag != "urlset":
        raise SourceNotValid(
            f"expected a sitemap urlset, received a <{root_tag}> document")
    if not entries:
        raise SourceNotValid("the job list parsed but contains no jobs")
    if not all("/job" in u for u, _ in entries[:5]):
        raise SourceNotValid("entries do not look like job addresses")


def read_job_list(xml_bytes):
    """Return (url, lastmod) for every entry in the published list."""
    root = ET.fromstring(xml_bytes)
    entries = []
    for url_el in root.iter():
        if not url_el.tag.endswith("}url") and url_el.tag != "url":
            continue
        loc = lastmod = None
        for child in url_el:
            tag = child.tag.split("}")[-1]
            if tag == "loc":
                loc = (child.text or "").strip()
            elif tag == "lastmod":
                lastmod = (child.text or "").strip()
        if loc:
            entries.append((loc, lastmod))
    return entries


