def check_unknown_stays_unknown(conn):
    """The source publishes no posted date. It must never be filled in.

    Inferring it from the change date or the retrieval time would be the first
    lie the system tells. See docs/source-novo-nordisk.md.
    """
    n = conn.execute(
        "SELECT count(*) FROM evidence WHERE published_date IS NOT NULL"
    ).fetchone()[0]
    if n:
        return False, f"{n} records have a posted date the source never published"
    return True, "no posted date was invented; the gap stays visible"


def check_required_entity(conn):
    n = conn.execute(
        "SELECT count(*) FROM evidence WHERE source_id IS NULL OR trim(source_id) = ''"
    ).fetchone()[0]
    if n:
        return False, f"{n} records cannot be attributed to a source"
    return True, "every record names the source it came from"

