import sys, urllib.parse, re, collections, json, pathlib
sys.path.insert(0,"."); import retro_test as rt, signals
STOP=set("""the and for of in a to with at on job jobs new senior sr jr i ii iii
associate assoc director dir manager mgr lead specialist us usa remote apply area""".split())
def stems(u):
    s=urllib.parse.unquote(u).split("/job/")[-1]
    s=re.sub(r"/\d+/?$","",s); s=re.sub(r"^R-\d+/","",s)
    w=[x.lower() for x in re.split(r"[-_/%\s]+", s) if x.isalpha() and len(x)>3]
    return [x for x in w if x not in STOP]
WANT={("novo","202412"),("novo","202506"),("lilly","202501"),
      ("lilly","202602"),("novo","202512")}
out={}; counts={}
for company,prefix in (("novo","careers.novonordisk.com/job/"),
                       ("lilly","careers.lilly.com/us/en/job/")):
    rows,err=rt.captures(prefix,"20240101","20260901")
    totals=collections.Counter(ts[:6] for ts,_ in rows)
    per=collections.defaultdict(collections.Counter)
    for ts,u in rows:
        for w in set(stems(u)):
            per[w][ts[:6]]+=1
    common={w:c for w,c in per.items() if sum(c.values())>=8}
    by=collections.defaultdict(list)
    for w,c in common.items():
        for s in signals.title_share_steps(c,totals,w,min_share=0.01,min_multiple=3,min_count=3):
            by[s["period"]].append([w,round(100*s["after_share"],1),s["count"]])
    for m,ws in by.items():
        if (company,m) in WANT:
            ws.sort(key=lambda t:-t[1])
            out[f"{company}|{m}"]={"words":ws,"captures":totals[m]}
    # funnel counts at four thresholds
    counts[company]=[]
    for sh,mu,ct in ((0.03,5,8),(0.02,4,5),(0.01,3,3),(0.005,2.5,2)):
        n=sum(len(signals.title_share_steps(c,totals,w,min_share=sh,min_multiple=mu,min_count=ct))
              for w,c in common.items())
        counts[company].append(n)
    counts[company+"_clusters"]=sum(1 for m,ws in by.items() if len(ws)>=4)
pathlib.Path("../research/cluster-examples.json").write_text(json.dumps(
    {"clusters":out,"funnel":counts},indent=2))
for k,v in out.items():
    print(f"\n  {k}  ({v['captures']} captures, {len(v['words'])} words stepped)")
    print("    " + ", ".join(f"{w}" for w,_,_ in v["words"][:14]))
print(f"\n  funnel: {json.dumps(counts)}")
