def check_collectors_call_what_exists(conn):
    """Every keyword a collector passes must exist in the function it calls.

    stable_digest gained a `replacement` parameter when Lilly's masking was
    rewritten. store() did not, and collect_lilly passes it — so the Lilly
    collector raised TypeError on its first stored page and nobody knew for a day.
    The suite stayed green throughout, because thirty checks examine the evidence
    and none examine the code that produces it.

    This is static: it reads the call sites and the signatures, hits no network,
    and takes milliseconds. It would have failed the moment the argument was added
    to one function and not the other.
    """
    import ast
    import inspect
    import importlib

    try:
        collect = importlib.import_module("collect")
    except Exception as exc:
        return False, f"cannot import the collector: {exc!r}"

    signatures = {}
    for name, obj in vars(collect).items():
        if inspect.isfunction(obj):
            try:
                signatures[name] = set(inspect.signature(obj).parameters)
            except (ValueError, TypeError):
                pass

    problems = []
    for path in sorted(ROOT.glob("collect*.py")):
        try:
            tree = ast.parse(path.read_text())
        except SyntaxError as exc:
            problems.append(f"{path.name} does not parse: {exc.msg}")
            continue
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call) or not isinstance(node.func, ast.Name):
                continue
            target = node.func.id
            if target not in signatures:
                continue
            for kw in node.keywords:
                if kw.arg and kw.arg not in signatures[target]:
                    problems.append(f"{path.name} calls {target}({kw.arg}=...) "
                                    f"but {target} has no such parameter")
    if problems:
        return False, "; ".join(sorted(set(problems))[:3])
    n = len(sorted(ROOT.glob("collect*.py")))

