def check_masking_survives_across_runs(conn):
    """Most pages stored twice must fingerprint identically once masked.
    The fetch-twice test is too weak. Two requests seconds apart returned the
    same value for Lilly's "sourceResponseTime", which is usually 0 and
    occasionally 1, so the mask passed and the field went unmasked for three
    collection runs. Comparing the versions already stored across runs catches
    what a short repeat cannot, and costs nothing.
    Real edits do happen, so this is a share rather than a requirement of zero.
    Lilly sat at 20% before the masks were rewritten to cover whole containers
    rather than the values inside them, and at 97% after.
    """
    import collect
    per_source = {}
    for source_id, paths in conn.execute(
            """SELECT source_id, group_concat(raw_path) FROM evidence
               GROUP BY source_id, url HAVING count(*) > 1"""):
        per_source.setdefault(source_id, []).append(paths.split(","))
    if not per_source:
        return True, "no page stored more than once yet; nothing to compare"
    noise = {}
    try:
        import collect_lilly
        noise["lilly-careers"] = (collect_lilly.PER_REQUEST_NOISE, b"")
    except Exception:
        pass
    out, bad = [], []
    for source_id, groups in sorted(per_source.items()):
        pats, rep = noise.get(source_id, (collect.PER_REQUEST_NOISE, b"<masked>"))
        same = 0
        for ps in groups:
            a = (ROOT / ps[-2]).read_bytes() if not Path(ps[-2]).is_absolute() else Path(ps[-2]).read_bytes()
            b = (ROOT / ps[-1]).read_bytes() if not Path(ps[-1]).is_absolute() else Path(ps[-1]).read_bytes()
            same += collect.stable_digest(a, pats, rep) == collect.stable_digest(b, pats, rep)
        share = same / len(groups)
        out.append(f"{source_id} {same}/{len(groups)} ({share:.0%})")
        if len(groups) >= 20 and share < 0.8:
            bad.append(f"{source_id}: only {share:.0%} of repeat fetches match "
                       f"after masking; per-request noise is being read as change")
    if bad:
        return False, "; ".join(bad)
    return True, "repeat fetches match after masking: " + ", ".join(out)
# Sources Telegraph collects itself, and can therefore vouch for. Adding a name
